"""Actual incremental graph changes, generated byte resources and database replay."""
import json, os, shlex, shutil, time
from pathlib import Path
from common import sha

GENERATOR='''from pathlib import Path
import os,sys
source=Path(sys.argv[1]).read_text().strip()
if not source.startswith('VALUE=') or not source[6:].isdigit():raise SystemExit('GEN_REJECT:input')
value=int(source[6:])
if value>100:raise SystemExit('GEN_REJECT:range')
out=Path(sys.argv[2]);out.mkdir(exist_ok=True)
for name,text in [('cfg.h','#define BIAS '+str(value)+'\\n'),('mirror.h','#define MIRROR '+str(value)+'\\n')]:
 p=out/(name+'.tmp');p.write_text(text)
# Both prerequisites have one grouped recipe. No consumer starts between these
# publications; this is NOT atomic publication to unrelated external processes.
for name in ('cfg.h','mirror.h'):os.replace(out/(name+'.tmp'),out/name)
with (out/'generation.log').open('a') as f:f.write(source+'\\n')
'''
MAKE='''CC=gcc
.PHONY: all clean
all: build/program
build:
\tmkdir -p build
build/cfg.h build/mirror.h &: schema.txt generator.py | build
\tpython3 generator.py schema.txt build
build/step.o: step.c build/cfg.h build/mirror.h | build
\t$(CC) -std=c17 -Ibuild -MMD -MP -c step.c -o $@
build/main.o: main.c | build
\t$(CC) -std=c17 -MMD -MP -c main.c -o $@
build/program: build/step.o build/main.o
\t$(CC) $^ -o $@
-include build/step.d build/main.d
clean:
\trm -f build/*.o build/*.d build/program
'''
STEP='#include "cfg.h"\n#include "mirror.h"\n_Static_assert(BIAS==MIRROR,"coherent generation");\nint step(int x){return 3*x+BIAS;}\n'
MAIN='#include <stdio.h>\nint step(int);int main(void){printf("%d\\n",step(4));return 0;}\n'

def execute(c):
    c.group='make-graph';d=c.root/'make';d.mkdir()
    for path,text in [('generator.py',GENERATOR),('Makefile',MAKE),('step.c',STEP),('main.c',MAIN),('schema.txt','VALUE=7\n')]:c.write('make/'+path,text)
    c.run(['make','--version']);c.run(['make','-j8'],d)
    c.require(c.run([d/'build/program'])=='19\n','initial graph value')
    names=['step.o','main.o','program']
    def stamps():return {p:(d/'build'/p).stat().st_mtime_ns for p in names}
    def build(expect,label):
        before=stamps();c.run(['make','-j8','--trace'],d);after=stamps()
        changed=sorted(p for p in names if before[p]!=after[p])
        c.require(changed==sorted(expect),'exact rebuilt set: '+label,changed)
    build([],'no-op');time.sleep(1.05)
    os.utime(d/'build',None);build([],'order-only directory')
    time.sleep(1.05);c.write('make/schema.txt','VALUE=9\n');build(['step.o','program'],'schema edit')
    c.require(c.run([d/'build/program'])=='21\n','schema semantic change')
    time.sleep(1.05);(d/'build/cfg.h').unlink();build(['step.o','program'],'header deletion')
    time.sleep(1.05);c.write('make/generator.py',GENERATOR+'# changed generator input\n');build(['step.o','program'],'generator edit')
    time.sleep(1.05);c.write('make/unrelated.txt','ignored\n');build([],'unrelated input')
    time.sleep(1.05);os.utime(d/'build/cfg.h',None);build(['step.o','program'],'normal header edge')
    before=sha(d/'build/cfg.h');time.sleep(1.05);c.write('make/schema.txt','FAIL\n')
    c.run(['make','-j8'],d,expected='nonzero',contains='GEN_REJECT:input')
    c.require(sha(d/'build/cfg.h')==before,'failed producer preserves previously coherent header')
    c.write('make/schema.txt','VALUE=11\n');c.run(['make','-j8'],d)
    c.require(c.run([d/'build/program'])=='23\n','repaired generator input')
    c.observe('T07.05.a','Actual depfile graph, independent main TU, header-deletion regeneration',['make/Makefile','make/build/step.d'])
    c.observe('T07.05.a','One grouped producer publishes two coherent headers before any parallel consumer',['make/generator.py','-j8 build traces'],True,
        ['Grouped Make scheduling is not a transaction for unrelated readers or sudden power loss.'])
    c.observe('T07.05.b','Order-only directory versus ordinary header invalidation and phony actions',['make rebuild-set checks'])
    c.observe('T07.05.c','Fresh/no-op/schema/deletion/generator/unrelated/failure recovery observed; exact rebuild sets checked',['make traces and output checks'])
    # Intentionally wrong order-only header edge; no depfile can silently repair it.
    bad=c.root/'bad-make';bad.mkdir()
    c.write('bad-make/cfg.h','#define VALUE 7\n')
    c.write('bad-make/main.c','#include "cfg.h"\nint main(void){return VALUE;}\n')
    c.write('bad-make/Makefile','all: app\napp: main.c | cfg.h\n\tgcc main.c -o app\n')
    c.run(['make'],bad);c.run([bad/'app'],expected=7)
    time.sleep(1.05);c.write('bad-make/cfg.h','#define VALUE 9\n');c.run(['make'],bad);c.run([bad/'app'],expected=7)
    c.write('bad-make/Makefile','all: app\napp: main.c cfg.h\n\tgcc main.c -o app\n');c.run(['make'],bad);c.run([bad/'app'],expected=9)
    c.observe('T07.05.b','Broken order-only cfg edge yields stale7; repairing ordinary edge yields9',['bad-make trace'],True)
    # Coarse-timestamp counterexample followed by content-identity invalidation.
    old=(bad/'cfg.h').stat().st_mtime_ns;oldhash=sha(bad/'cfg.h')
    c.write('bad-make/cfg.h','#define VALUE 5\n');os.utime(bad/'cfg.h',ns=(old,old))
    c.run(['make'],bad);c.run([bad/'app'],expected=9)
    c.require(sha(bad/'cfg.h')!=oldhash,'digest distinguishes equal timestamps')
    c.run(['make','-B'],bad);c.run([bad/'app'],expected=5)
    c.observe('T07.05.c','Same-time changed bytes defeat timestamp freshness; hash mismatch invalidates then rebuilds',['bad-make/cfg.h','digest and run checks'],True,
        ['This conservative digest policy scans full input bytes and rebuilds affected graph; hashing is not free or provenance authentication.'])

    c.group='ninja-database';d=c.root/'ninja';d.mkdir()
    c.write('ninja/cfg.h','#define VALUE 7\n');c.write('ninja/main.c','#include "cfg.h"\nint value(void){return VALUE;}\n')
    ninja='''rule cc
  command = gcc -std=c17 -MMD -MF $out.d $flags -c $in -o $out
  depfile = $out.d
  deps = gcc
build debug.o: cc main.c
  flags = -O0 -g
build release.o: cc main.c
  flags = -O2
'''
    c.write('ninja/build.ninja',ninja);c.run(['ninja','-d','explain'],d)
    c.require('no work to do' in c.run(['ninja','-d','explain'],d),'Ninja no-op')
    time.sleep(1.05);c.write('ninja/cfg.h','#define VALUE 9\n');out=c.run(['ninja','-d','explain'],d)
    c.require('cfg.h' in out and 'debug.o' in out and 'release.o' in out,'depfile edges cause both consumers')
    time.sleep(1.05);c.write('ninja/main.c','#include "cfg.h"\nint value(void){return VALUE+1;}\n')
    out=c.run(['ninja','-d','explain'],d);c.require('main.c' in out and 'debug.o' in out and 'release.o' in out,'source edit invalidates both configurations')
    before=sha(d/'release.o');c.write('ninja/build.ninja',ninja.replace('flags = -O2','flags = -Os'))
    out=c.run(['ninja','-d','explain'],d);c.require('command line changed' in out,'flag-only change invalidates')
    database=json.loads(c.run(['ninja','-t','compdb','cc'],d))
    c.require(len(database)==2 and len({x['output'] for x in database})==2,'two commands preserved for one source')
    c.write('ninja/compile_commands.json',json.dumps(database,indent=2))
    for row in database:
        original=sha(Path(row['directory'])/row['output']);c.run(shlex.split(row['command']),row['directory'])
        c.require(sha(Path(row['directory'])/row['output'])==original,'exact TU replay identity',row['output'])
    # The argument contains a literal space. JSON argv avoids shell quoting guesses.
    c.write('ninja/space.c','const char text[]=LABEL;\n')
    argv=['gcc','-std=c17','-DLABEL="two words"','-c','space.c','-o','space.o']
    c.write('ninja/space_commands.json',json.dumps([{'directory':str(d),'file':'space.c','arguments':argv,'output':'space.o'}]))
    c.run(argv,d);c.require('two words' in c.run(['strings','space.o'],d),'one spaced compiler argument retained')
    # Duplicate path spellings are observed, not assumed normalized by every tool.
    c.run(['ninja','-t','deps'],d);c.run(['ninja','-t','graph'],d)
    alias=ninja.replace('build release.o: cc main.c','build release.o: cc ./main.c')
    c.write('ninja/build.ninja',alias);c.run(['ninja','-d','explain'],d)
    c.require(len(json.loads(c.run(['ninja','-t','compdb','cc'],d)))==2,'spelled paths retain configuration identities')
    for leaf,claim in [('a','Depfile and command-line invalidation actually observed; graph/deps saved'),
                       ('b','Two configuration/output identities retained; link and generation deliberately absent from compdb'),
                       ('c','Exact cwd/argv replay reconstructs each object under same inputs')]:
        c.observe('T07.08.'+leaf,claim,['ninja commands','ninja/compile_commands.json'])
    c.observe('T07.08.a','main.c and ./main.c graph spellings compared without assuming universal path normalization',['Ninja graph/compdb'],True)
    c.observe('T07.08.b','Spaced macro stays one argument in explicit arguments array',['ninja/space_commands.json'],True)
    olddir=d;newdir=c.root/'ninja-relocated';shutil.copytree(d,newdir)
    # Keep the original directory but remove the generated prerequisite: the stale
    # database still addresses the old root and must not be credited as relocation.
    (olddir/'cfg.h').unlink();row=database[0]
    c.run(shlex.split(row['command']),row['directory'],expected='nonzero',contains='cfg.h')
    current=json.loads(c.run(['ninja','-t','compdb','cc'],newdir))
    c.require(all(x['directory']==str(newdir) for x in current),'database regenerated in new source root')
    for row in current:c.run(shlex.split(row['command']),row['directory'])
    c.observe('T07.08.c','Stale root database fails at missing old input; regenerated database addresses relocated tree',['ninja-relocated compdb/replay'],True)
    # Absolute and relative names are distinct graph nodes even for one header.
    c.write('ninja-relocated/build.ninja',alias+f'build alias-check: phony cfg.h {newdir}/cfg.h\n')
    graph=c.run(['ninja','-t','graph','alias-check'],newdir)
    c.require('label="cfg.h"' in graph and str(newdir/'cfg.h') in graph,'same header has distinct absolute/relative graph nodes')
    # A real schema producer joins the Ninja graph; compare its rebuild set.
    c.write('ninja-relocated/schema.txt','VALUE=11\n')
    c.write('ninja-relocated/generate.py','from pathlib import Path\nv=Path("schema.txt").read_text().strip().split("=")[1]\nPath("cfg.h").write_text("#define VALUE "+v+"\\n")\n')
    generated=alias+'rule generate\n  command = python3 generate.py\nbuild cfg.h: generate schema.txt generate.py\n'
    c.write('ninja-relocated/build.ninja',generated);out=c.run(['ninja','-d','explain'],newdir)
    c.require('generate.py' in out and 'debug.o' in out and 'release.o' in out,'schema generation reaches both consumers')

    c.group='generated-resource';d=c.root/'resource';d.mkdir()
    generator='''from pathlib import Path
import sys
paths=Path(sys.argv[1]).read_text().splitlines()
if len(set(paths))!=len(paths):raise SystemExit('RESOURCE_REJECT:duplicate')
data=b''.join(Path(x).read_bytes() for x in paths)
text='static const unsigned char resource[]={' + ','.join(map(str,data or b'\\0')) + '};\\n'
text+='static const unsigned long resource_size='+str(len(data))+';\\n'
out=Path(sys.argv[2]);tmp=out.with_suffix('.tmp');tmp.write_text(text);tmp.replace(out)
'''
    c.write('resource/embed.py',generator);c.write('resource/fragments.txt','first.bin\n')
    (d/'first.bin').write_bytes(bytes([0,127,128,255]))
    c.write('resource/probe.c','#include <stdio.h>\n#include "resource.h"\nint main(void){printf("%lu:",resource_size);for(unsigned long i=0;i<resource_size;i++)printf("%02x",resource[i]);puts("");return 0;}\n')
    for data in (bytes([0,127,128,255]),b'\xff\x00',b''):
        (d/'first.bin').write_bytes(data);c.run(['python3','embed.py','fragments.txt','resource.h'],d)
        c.run(['gcc','-std=c17','-pedantic-errors','probe.c','-o','probe'],d)
        c.require(c.run([d/'probe'])==str(len(data))+':'+data.hex()+'\n','independent resource hex/length',list(data))
    (d/'first.bin').unlink();c.run(['python3','embed.py','fragments.txt','resource.h'],d,expected='nonzero',contains='first.bin')
    (d/'first.bin').write_bytes(b'\x00\x7f');(d/'second.bin').write_bytes(b'\x80\xff')
    c.write('resource/fragments.txt','first.bin\nsecond.bin\n')
    manifest={'paths':['first.bin','second.bin'],'hashes':{p:sha(d/p) for p in ['first.bin','second.bin']}}
    c.write('resource/resource-manifest.json',json.dumps(manifest,indent=2))
    c.run(['python3','embed.py','fragments.txt','resource.h'],d);c.run(['gcc','-std=c17','probe.c','-o','probe'],d)
    c.require(c.run([d/'probe'])=='4:007f80ff\n','ordered resource fragments')
    c.write('resource/fragments.txt','second.bin\nfirst.bin\n')
    c.require((d/'fragments.txt').read_text().splitlines()!=manifest['paths'],'fragment manifest rejects reorder')
    c.observe('T07.07.b','Exact high-bit/zero bytes, changes, truncation, empty ISO array representation and missing input rejection',['resource commands'])
    c.observe('T07.07.b','Ordered manifest distinguishes reorder from equal unordered file set',['resource/resource-manifest.json'],True)
    c.write('resource/fragments.txt','first.bin\nsecond.bin\n')
    (d/'resource.h').unlink()
    c.write('resource/build.ninja','''rule embed
  command = python3 embed.py fragments.txt resource.h
build resource.h: embed embed.py fragments.txt first.bin second.bin
rule cc
  command = gcc -std=c17 -pedantic-errors probe.c -o graph-probe
build graph-probe: cc probe.c resource.h
default graph-probe
''')
    c.run(['ninja','-d','explain'],d);c.require(c.run([d/'graph-probe'])=='4:007f80ff\n','resource graph initial output')
    time.sleep(1.05);(d/'second.bin').write_bytes(b'\xff');out=c.run(['ninja','-d','explain'],d)
    c.require('second.bin' in out and c.run([d/'graph-probe'])=='3:007fff\n','resource byte change invalidates generated header and consumer')
    (d/'second.bin').unlink();c.run(['ninja'],d,expected='nonzero',contains='second.bin')
